"""Core functionality for the pkg package."""


def greet(name):
    """Return a greeting for the given name."""
    return "Hello, {}!".format(name)

"""Tests for the pkg package."""

from pkg import greet
from pkg.core import greet as core_greet


def test_greet():
    assert greet("World") == "Hello, World!"


def test_greet_empty_name():
    assert greet("") == "Hello, !"


def test_export_is_core_function():
    assert greet is core_greet
